CREATE function [dbo].[funcGetChequeNo] ( @VN nvarchar(50), @VoucherId int, @CAId int )returns nvarchar(MAX) as Begin Declare @ChequeNo nvarchar(MAX); set @ChequeNo = '' if @VN like 'BPV%' Begin select @ChequeNo = ChequeNo from BankPaymentMaster where BPId = @VoucherId and VN = @VN and CAId = @CAId if @ChequeNo = '' select @ChequeNo = ChequeNo from BankPaymentMaster where VN = @VN End else if @VN like 'BRV%' Begin select @ChequeNo = ChequeNo from BankReceiptMaster where BRId = @VoucherId and VN = @VN and CAId = @CAId End else if @VN like 'CPV%' Begin set @ChequeNo = 'Cash'; End else if @VN like 'CRV%' Begin set @ChequeNo = 'Cash'; End else if @VN like 'PV%' Begin set @ChequeNo = 'Purchase'; End else if @VN like 'SAL%' Begin set @ChequeNo = 'Sale'; End return @ChequeNo End